		parameters: Type.Object({
			source: Type.String({
				description:
					"The Mermaid source, starting with its diagram type (`flowchart TD`, `sequenceDiagram`, `stateDiagram-v2`, `mindmap`, …). No fences, no surrounding prose.",
			}),
			title: Type.Optional(
