    #[test]
    fn leg_state_rejects_stale_session_tokens() {
        let leg = LiveLegState::new();
        leg.set_session("alpha", "new-session");
        assert!(!leg.report_thinking("old-session", "high"));
        assert!(leg.report_thinking("new-session", "high"));
    }

