        let mut turns = state.0.turn_rx.lock().await.take().unwrap();
        assert!(matches!(
            turns.try_recv(),
            Err(mpsc::error::TryRecvError::Empty)
        ));
        worker.abort();
        assert!(worker.await.unwrap_err().is_cancelled());
